mapper.select:
select
    ${params.viewData},
    sum(doit.amount_after * doit.currency_rate) as value
from dmp_order_info doi
inner join dmp_order_item_split doit on doit.order_id = doi.id
where doi.platform_create_time >= #{lastsMonth}

    ${params.permissionSql }

group by ${params.groupData}

select
    ${params.viewData},
sum(doit.quantity) as value
from dmp_order_info doi
inner join dmp_order_item_split doit on doit.order_id = doi.id
where doi.platform_create_time >= #{lastsMonth}

    ${params.permissionSql }

group by ${params.groupData}

select
${params.viewData},
sum(doit.amount_after * doit.currency_rate) as value
from dmp_order_info doi
inner join dmp_order_item_split doit on doit.order_id = doi.id
inner join product_detail pd on pd.is_deleted = false and doit.sku_no = pd.sku_no
inner join product_info pi on pi.is_deleted = false and pd.product_id = pi.id
where doi.platform_create_time >= #{lastsMonth}

    ${params.permissionSql }

group by ${params.groupData}

select
${params.viewData},
sum(doit.quantity) as value
from dmp_order_info doi
inner join dmp_order_item_split doit on doit.order_id = doi.id
inner join product_detail pd on pd.is_deleted = false and doit.sku_no = pd.sku_no
inner join product_info pi on pi.is_deleted = false and pd.product_id = pi.id
where doi.platform_create_time >= #{lastsMonth}

    ${params.permissionSql }

group by ${params.groupData}
